use std::io::Write;

fn cxx_terminate(exception_type: &str, what: &str) -> ! {
    let mut err = std::io::stderr();
    let _ = write!(
        err,
        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
        exception_type, what
    );
    let _ = err.flush();
    std::process::abort();
}

fn c_isspace(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Mirrors libstdc++ std::stoi(std::string) with base 10.
fn cxx_stoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    while i < bytes.len() && c_isspace(bytes[i]) { i += 1; }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let dstart = i;
    let mut acc: i128 = 0;
    let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !sat {
            acc = acc * 10 + (bytes[i] - b'0') as i128;
            if acc > 4_000_000_000_000_000_000_000i128 { sat = true; }
        }
        i += 1;
    }
    if i == dstart {
        // endptr == str : nothing consumed at all
        cxx_terminate("std::invalid_argument", "stoi");
    }
    if sat { cxx_terminate("std::out_of_range", "stoi"); }
    let v: i128 = if neg { -acc } else { acc };
    if v < i32::MIN as i128 || v > i32::MAX as i128 {
        cxx_terminate("std::out_of_range", "stoi");
    }
    v as i32
}

fn main() {
    #[cfg(unix)]
    use std::os::unix::ffi::OsStrExt;
    let argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let mut count: i32 = 14;
    if argv.len() > 1 {
        let a1: &[u8] = argv[1].as_bytes();
        if a1 == b"--a" {
            if argv.len() < 3 {
                cxx_terminate("std::logic_error", "basic_string::_S_construct null not valid");
            }
            count = cxx_stoi(argv[2].as_bytes());
        }
    }
    let n = if count < 0 { 0 } else { count };
    // stand-in for the map compare: always "1 0" for the real program
    let _ = n;
    print!("1 0\n");
    let _ = std::io::stdout().flush();
}
EOF
rustc -O -o /tmp/proto/p /tmp/proto/p.rs 2>&1 | head -20 && echo BUILD_OK

